    20→}
    21→
    22→public struct Obligation<phantom MarketType> has key, store {
    23→    id: UID,
    24→    // with market id, no need to track version
    25→    lending_market_id: ID,
    26→    debts: WitTable<ObligationDebts, TypeName, Debt>,
    27→    ctokens: CTokenTable,
    28→
    29→    emode_group: u8,
    30→}
    31→
    32→public fun id(self: &ObligationOwnerCap): ID {
    33→    self.obligation_id
    34→}
    35→
    36→public(package) fun emode_group<MarketType>(self: &Obligation<MarketType>): u8 {
    37→    self.emode_group
    38→}
    39→
    40→public(package) fun debts<MarketType>(
    41→    self: &Obligation<MarketType>,
    42→): &WitTable<ObligationDebts, TypeName, Debt> {
    43→    &self.debts
    44→}
    45→
    46→public(package) fun market_id<MarketType>(self: &Obligation<MarketType>): ID {
    47→    self.lending_market_id
    48→}
    49→
    50→public(package) fun new<MarketType>(
    51→    lending_market_id: ID,
    52→    emode_group: u8,
    53→    ctx: &mut TxContext,
    54→): (Obligation<MarketType>, ObligationOwnerCap) {
    55→    let obligation = Obligation {
    56→        id: object::new(ctx),
    57→        lending_market_id,
    58→        debts: wit_table::new(ObligationDebts {}, true, ctx),
    59→        ctokens: ctoken_table::new(ctx),
    60→        emode_group,
    61→    };
    62→
    63→    let cap = ObligationOwnerCap {
    64→        id: object::new(ctx),
    65→        obligation_id: object::id(&obligation),
    66→        market_type: type_name::with_defining_ids<MarketType>(),
    67→        market_id: lending_market_id,
    68→    };
    69→    (obligation, cap)
    70→}
    71→
    72→public(package) fun accrue_interest<MarketType>(
    73→    self: &mut Obligation<MarketType>,
    74→    name: TypeName,
    75→    asset_borrow_index: Decimal,
    76→): &mut Debt {
    77→    let debt = wit_table::borrow_mut(ObligationDebts {}, &mut self.debts, name);
    78→    debt.accrue_interest(asset_borrow_index);
    79→    debt
    80→}
    81→
    82→public(package) fun deposit_ctoken<MarketType, CoinType>(
    83→    self: &mut Obligation<MarketType>,
    84→    ctoken: Balance<CToken<MarketType, CoinType>>,
    85→) {
    86→    assert!(
    87→        !self.debts.contains(type_name::with_defining_ids<CoinType>()),
    88→        error::obligation_deposit_borrowed_asset(),
    89→    );
    90→    if (!self.ctokens.is_supporting_collateral<MarketType, CoinType>()) {
    91→        self.ctokens.support_collateral_token<MarketType, CoinType>();
    92→    };
    93→    self.ctokens.join_ctoken(ctoken);
    94→}
    95→
    96→public(package) fun withdraw_ctokens<MarketType, CoinType>(
    97→    self: &mut Obligation<MarketType>,
    98→    amount: u64,
    99→): Balance<CToken<MarketType, CoinType>> {
   100→    assert!(
   101→        self.ctokens.is_supporting_collateral<MarketType, CoinType>(),
   102→        error::obligation_withdraw_no_deposit(),
   103→    );
   104→    self.ctokens.split_ctoken<MarketType, CoinType>(amount)
   105→}
   106→
   107→/// Try borrow the asset, increase the debt. Returns the latest asset debt.
   108→public(package) fun try_borrow_asset<MarketType, CoinType>(
   109→    self: &mut Obligation<MarketType>,
   110→    amount: u64,
   111→    asset_borrow_index: Decimal,
   112→): Decimal {
   113→    let name = type_name::with_defining_ids<CoinType>();
   114→
   115→    let amount = math::float::from(amount);
   116→
   117→    if (!self.debts.contains(type_name::with_defining_ids<CoinType>())) {
   118→        // no borrow before, init borrow
   119→
   120→        // do not allow borrowing of collateral asset, mess up book keeping
   121→        assert!(
   122→            !self.ctokens.is_supporting_collateral<MarketType, CoinType>(),
   123→            error::obligation_borrow_collateral_asset(),
   124→        );
   125→
   126→        wit_table::add(
   127→            ObligationDebts {},
   128→            &mut self.debts,
   129→            name,
   130→            debt::new(amount, asset_borrow_index),
   131→        );
   132→
   133→        return amount
   134→    };
   135→
   136→    let debt = self.accrue_interest(type_name::with_defining_ids<CoinType>(), asset_borrow_index);
   137→
   138→    // this is safe to do because it has accrued interest before
   139→    debt.unsafe_increase(amount);
   140→    debt.unsafe_debt_amount()
   141→}
   142→
   143→/// Obligation repays debt, returns 
   144→public(package) fun repay_debt<MarketType, CoinType>(
   145→    self: &mut Obligation<MarketType>,
   146→    amount: u64,
   147→    asset_borrow_index: Decimal,
   148→): u64 {
   149→    let _ = self.accrue_interest(type_name::with_defining_ids<CoinType>(), asset_borrow_index);
   150→    self.unsafe_repay_debt_only<MarketType, CoinType>(amount)
   151→}
   152→
   153→/// Checks the invariants after borrow or repay that must be met
   154→public(package) fun enforce_post_borrow_repay_invariant<MarketType, CoinType>(
   155→    self: &Obligation<MarketType>,
   156→    min_borrow_amount: u64
   157→) {
   158→    let coin_type = type_name::with_defining_ids<CoinType>();
   159→
   160→    if (!self.has_debt<MarketType>(coin_type)){
   161→        return
   162→    };
   163→
   164→    let current_debt = self.debt<MarketType>(coin_type).unsafe_debt_amount();
   165→    assert!(current_debt.ge_u64(min_borrow_amount), error::obligation_borrow_below_min());
   166→}
   167→
   168→/// Directly updating the debt repay, without checking if interest is up to date.
   169→/// The caller makes sure the obligation interest is already updated to date
   170→public(package) fun unsafe_repay_debt_only<MarketType, CoinType>(
   171→    self: &mut Obligation<MarketType>,
   172→    amount: u64,
   173→): u64 {
   174→    let name = type_name::with_defining_ids<CoinType>();
   175→    let debt = wit_table::borrow_mut(ObligationDebts {}, &mut self.debts, name);
   176→
   177→    let debt_amount = debt.unsafe_debt_amount().ceil();
   178→
   179→    let residual = if (debt_amount <= amount) {
   180→        debt.cleared();
   181→
   182→        // repay a bit more than actually owned, almost neglegible
   183→        amount - debt_amount
   184→    } else {
   185→        debt.unsafe_decrease(math::float::from(amount));
   186→        0
   187→    };
   188→
   189→    if (!debt.has_debt()) {
   190→        wit_table::remove(ObligationDebts {}, &mut self.debts, name);
   191→    };
   192→
   193→    residual
   194→}
   195→
   196→/// Make sure the type name is ctoken type
   197→public fun ctoken_amount_by_coin<MarketType>(
   198→    self: &Obligation<MarketType>,
   199→    name: TypeName,
   200→): u64 {
   201→    self.ctokens.ctoken_value_by_coin_type(name)
   202→}
   203→
   204→// Queries the debt by coin type name. If name does not exist, reverts.
   205→public fun debt<MarketType>(self: &Obligation<MarketType>, name: TypeName): &Debt {
   206→    self.debts.borrow(name)
   207→}
   208→
   209→// return the debt types
   210→public fun debt_types<MarketType>(self: &Obligation<MarketType>): vector<TypeName> {
   211→    self.debts.keys()
   212→}
   213→
   214→// return the deposit types
   215→public fun deposit_types<MarketType>(self: &Obligation<MarketType>): vector<TypeName> {
   216→    self.ctokens.supported_coin_types()
   217→}
   218→
   219→public(package) fun has_debt<MarketType>(self: &Obligation<MarketType>, debt_type: TypeName): bool {
   220→    self.debts.contains(debt_type)
   221→}
   222→
   223→public struct ObligationDebts has drop {}
   224→
   225→#[test_only]
   226→public struct MainMarket {}
   227→
   228→#[test_only]
   229→public struct SUI {}
   230→
   231→#[test_only]
   232→public struct BTC {}
   233→
   234→#[test]
   235→public(package) fun debt_works() {
   236→    let admin = @0xAD;
   237→    let mut scenario_value = sui::test_scenario::begin(admin);
   238→    let ctx = scenario_value.ctx();
   239→    let market = object::new(ctx);
   240→
   241→    let (mut obligation, cap) = new<MainMarket>(*market.uid_as_inner(), 0, ctx);
   242→
   243→    let asset_borrow_index = math::float::from_quotient(15, 10);
   244→    let amount = 1;
   245→
   246→    assert!(!obligation.debt_types().contains(&type_name::with_defining_ids<SUI>()));
   247→
   248→    // initial borrow
   249→    let borrowed = obligation.try_borrow_asset<MainMarket, SUI>(amount, asset_borrow_index);
   250→    assert!(borrowed == math::float::from(amount));
   251→    let (borrowed, index) = obligation.debt<MainMarket>(type_name::with_defining_ids<SUI>()).snapshot();
   252→    assert!(borrowed == math::float::from(amount));
   253→    assert!(index == asset_borrow_index);
   254→    assert!(obligation.debt_types().contains(&type_name::with_defining_ids<SUI>()));
   255→
   256→    // future borrows
   257→    let asset_borrow_index = math::float::from_quotient(21, 10);
